BOOL FollowerMon_IsLargeSpecies(u16 species)
{
    if (species > SPECIES_ARCEUS) {
        return FALSE;
    }

    return sFollowerMonParams[species].isLarge;
}

u8 FollowerMon_GetBounceSpeed(u16 species)
{
    if (species > SPECIES_ARCEUS) {
        return FOLLOWER_BOUNCE_FAST;
    }

    return sFollowerMonParams[species].bounceSpeed;
}
